private final class StudioResizeHandle: NSView {
    enum Axis { case horizontal, vertical }
    let axis: Axis; var dragged: ((CGFloat) -> Void)?; private var lastPoint: NSPoint?
    init(axis: Axis) { self.axis = axis; super.init(frame: .zero); wantsLayer = true }
    required init?(coder: NSCoder) { fatalError() }
    override func resetCursorRects() { addCursorRect(bounds, cursor: axis == .vertical ? .resizeLeftRight : .resizeUpDown) }
    override func mouseDown(with event: NSEvent) { lastPoint = event.locationInWindow }
    override func mouseDragged(with event: NSEvent) { guard let p = lastPoint else { return }; let n = event.locationInWindow; let d = axis == .vertical ? n.x-p.x : n.y-p.y; lastPoint=n; dragged?(d) }
}
private final class StudioLayoutState { static let shared=StudioLayoutState(); var leftWidth:CGFloat=330; var rightWidth:CGFloat=350; var arrangementFraction:CGFloat=0.58; weak var leftHandle:StudioResizeHandle?; weak var rightHandle:StudioResizeHandle?; weak var horizontalHandle:StudioResizeHandle? }

private final class LiveArrangementView: NSView {
    var tracks:[EngineTrack]=[]; var clips:[EngineClip]=[]; var selectedTrackID:Int?; var selectedClipID:Int?; var onSelectTrack:((Int)->Void)?; var onSelectClip:((Int,Int)->Void)?
    private let colors:[NSColor] = [.systemBlue,.systemRed,.systemGreen,.systemOrange,.systemPurple,.systemTeal,.systemGray]
    override var isFlipped:Bool { true }
    override func draw(_ dirtyRect:NSRect) {
        NSColor.csArrangement.setFill(); bounds.fill(); let header:CGFloat=170, top:CGFloat=58
        NSColor.csPanelStrong.setFill(); NSRect(x:0,y:0,width:header,height:bounds.height).fill(); NSColor.csTop.setFill(); NSRect(x:header,y:0,width:max(0,bounds.width-header),height:top).fill()
        let maxBeat=max(16.0,clips.map{$0.startBeat+$0.lengthBeats}.max() ?? 16.0), beatW=max(8,(bounds.width-header-12)/CGFloat(maxBeat))
        let sections=["A – Einführung","B – Entwicklung","C – Höhepunkt","D – Ausklang"]
        let sectionColors=[NSColor.systemGreen.withAlphaComponent(0.18),NSColor.systemBlue.withAlphaComponent(0.16),NSColor.systemRed.withAlphaComponent(0.15),NSColor.systemPurple.withAlphaComponent(0.15)]
        for i in 0..<4 { let x=header+CGFloat(i)*(bounds.width-header)/4; let w=(bounds.width-header)/4; sectionColors[i].setFill(); NSRect(x:x,y:24,width:w,height:34).fill(); (sections[i] as NSString).draw(in:NSRect(x:x+4,y:34,width:w-8,height:16),withAttributes:[.font:NSFont.systemFont(ofSize:11,weight:.medium),.foregroundColor:NSColor.csText]) }
        for b in stride(from:0,through:Int(ceil(maxBeat)),by:4) { let x=header+CGFloat(b)*beatW; NSColor.csLine.setStroke(); let p=NSBezierPath(); p.move(to:NSPoint(x:x,y:top)); p.line(to:NSPoint(x:x,y:bounds.height)); p.stroke(); ("\(b+1)" as NSString).draw(at:NSPoint(x:x+3,y:6),withAttributes:[.font:NSFont.systemFont(ofSize:10),.foregroundColor:NSColor.secondaryLabelColor]) }
        let n=max(1,tracks.count), rowH=max(52,(bounds.height-top)/CGFloat(n))
        for (i,t) in tracks.enumerated() { let y=top+CGFloat(i)*rowH, c=colors[i%colors.count]; (t.id==selectedTrackID ? NSColor.selectedContentBackgroundColor.withAlphaComponent(0.12):NSColor.csPanelStrong).setFill(); NSRect(x:0,y:y,width:header,height:rowH).fill(); c.setFill(); NSBezierPath(roundedRect:NSRect(x:8,y:y+8,width:16,height:max(24,rowH-16)),xRadius:3,yRadius:3).fill(); ("\(i+1)" as NSString).draw(in:NSRect(x:9,y:y+18,width:14,height:14),withAttributes:[.font:NSFont.systemFont(ofSize:10,weight:.bold),.foregroundColor:NSColor.white]); (t.name as NSString).draw(in:NSRect(x:33,y:y+9,width:128,height:18),withAttributes:[.font:NSFont.systemFont(ofSize:13,weight:.semibold),.foregroundColor:NSColor.csText]); ("M    S    ●" as NSString).draw(in:NSRect(x:33,y:y+31,width:100,height:16),withAttributes:[.font:NSFont.systemFont(ofSize:11),.foregroundColor:NSColor.secondaryLabelColor]); NSColor.csLine.setStroke(); let l=NSBezierPath(); l.move(to:NSPoint(x:0,y:y+rowH)); l.line(to:NSPoint(x:bounds.width,y:y+rowH)); l.stroke()
            for clip in clips where clip.trackId==t.id { let x=header+CGFloat(clip.startBeat)*beatW, w=max(12,CGFloat(clip.lengthBeats)*beatW), r=NSRect(x:x,y:y+8,width:min(w,max(4,bounds.width-x-4)),height:max(20,rowH-16)); c.withAlphaComponent(clip.id==selectedClipID ? 0.30:0.18).setFill(); NSBezierPath(roundedRect:r,xRadius:5,yRadius:5).fill(); if clip.id==selectedClipID { c.setStroke(); let q=NSBezierPath(roundedRect:r,xRadius:5,yRadius:5); q.lineWidth=2; q.stroke() }; for note in clip.notes.prefix(500) { let nx=x+CGFloat(note.startBeat)*beatW, nw=max(2,CGFloat(note.lengthBeats)*beatW), pitch=CGFloat(127-note.note)/127, ny=r.minY+4+pitch*max(1,r.height-10); c.setFill(); NSRect(x:nx,y:ny,width:min(nw,max(1,r.maxX-nx)),height:2).fill() } }
        }
        if tracks.isEmpty { ("Noch keine Spur – MIDI importieren oder + drücken" as NSString).draw(in:NSRect(x:header+24,y:top+28,width:430,height:28),withAttributes:[.font:NSFont.systemFont(ofSize:15,weight:.medium),.foregroundColor:NSColor.secondaryLabelColor]) }
    }
    override func mouseDown(with event:NSEvent) { let p=convert(event.locationInWindow,from:nil), header:CGFloat=170, top:CGFloat=58; guard p.y>=top,!tracks.isEmpty else{return}; let rowH=max(52,(bounds.height-top)/CGFloat(max(1,tracks.count))), i=min(tracks.count-1,max(0,Int((p.y-top)/rowH))), t=tracks[i]; selectedTrackID=t.id; if p.x>header { let maxBeat=max(16.0,clips.map{$0.startBeat+$0.lengthBeats}.max() ?? 16.0), beatW=max(8,(bounds.width-header-12)/CGFloat(maxBeat)), beat=Double((p.x-header)/beatW); if let c=clips.first(where:{$0.trackId==t.id && beat >= $0.startBeat && beat <= $0.startBeat+$0.lengthBeats}) { selectedClipID=c.id; onSelectClip?(t.id,c.id) } }; onSelectTrack?(t.id); needsDisplay=true }
}

private final class LivePianoRollView:NSView {
    var notes:[EngineMidiNote]=[]; var title="Keine MIDI-Auswahl"; override var isFlipped:Bool { true }
    override func draw(_ dirtyRect:NSRect) { NSColor.csEditor.setFill(); bounds.fill(); (title as NSString).draw(at:NSPoint(x:10,y:7),withAttributes:[.font:NSFont.systemFont(ofSize:13,weight:.semibold),.foregroundColor:NSColor.csText]); guard !notes.isEmpty else { ("Clip auswählen, um seine echten MIDI-Noten zu sehen" as NSString).draw(at:NSPoint(x:60,y:48),withAttributes:[.font:NSFont.systemFont(ofSize:13),.foregroundColor:NSColor.secondaryLabelColor]); return }; let minN=notes.map{$0.note}.min()!, maxN=notes.map{$0.note}.max()!, span=max(12,maxN-minN+1), maxBeat=max(4.0,notes.map{$0.startBeat+$0.lengthBeats}.max() ?? 4.0), left:CGFloat=48, top:CGFloat=30, bw=max(8,(bounds.width-left-8)/CGFloat(maxBeat)), rh=max(4,(bounds.height-top-8)/CGFloat(span)); for b in 0...Int(ceil(maxBeat)) { let x=left+CGFloat(b)*bw; NSColor.csLine.withAlphaComponent(0.45).setStroke(); let p=NSBezierPath(); p.move(to:NSPoint(x:x,y:top)); p.line(to:NSPoint(x:x,y:bounds.height)); p.stroke() }; for n in notes { let x=left+CGFloat(n.startBeat)*bw,y=top+CGFloat(maxN-n.note)*rh,w=max(3,CGFloat(n.lengthBeats)*bw); NSColor.systemGreen.setFill(); NSBezierPath(roundedRect:NSRect(x:x,y:y,width:min(w,max(1,bounds.width-x-4)),height:max(3,rh-1)),xRadius:2,yRadius:2).fill() } }
}
