        browserList.subviews.forEach{$0.removeFromSuperview()}; browserTitle.stringValue="Plugins"; browserButtons.forEach{$0.isEnabled=false}; if let search=browserCard.subviews.compactMap({$0 as? NSSearchField}).first(where:{$0.identifier?.rawValue=="browserSearch"}) { search.isEnabled=false; search.placeholderString="Plugin-Anbindung folgt" }
        inspectorButtons.forEach{$0.isEnabled=false}; inspectorCard.subviews.filter{$0.identifier?.rawValue.hasPrefix("chain_")==true}.forEach{$0.isHidden=true}; inspectorCard.subviews.filter{$0.identifier?.rawValue.hasPrefix("editor_")==true}.forEach{$0.isHidden=false}; syncLiveDAW() }
