    private func installReadableTypography(){func enlarge(_ r:NSView){for v in r.subviews{if let f=v as? NSTextField,let font=f.font{f.font=.systemFont(ofSize:max(font.pointSize+2,13))}else if let b=v as? NSButton{b.font=.systemFont(ofSize:13,weight:.medium)};enlarge(v)}};enlarge(view);timeLabel.font=.monospacedDigitSystemFont(ofSize:19,weight:.semibold);inspectorTitle.font=.systemFont(ofSize:15,weight:.bold);playButton.font=.systemFont(ofSize:20,weight:.bold);stopButton.font=.systemFont(ofSize:18,weight:.bold);recordButton.font=.systemFont(ofSize:20,weight:.bold)}
    private func installResizablePanes(){let s=StudioLayoutState.shared;guard s.leftHandle==nil else{return};let l=StudioResizeHandle(axis:.vertical),r=StudioResizeHandle(axis:.vertical),h=StudioResizeHandle(axis:.horizontal);view.addSubview(l);view.addSubview(r);view.addSubview(h);s.leftHandle=l;s.rightHandle=r;s.horizontalHandle=h;l.dragged={[weak self]d in s.leftWidth=min(520,max(280,s.leftWidth+d));self?.applyResizableLayout()};r.dragged={[weak self]d in s.rightWidth=min(520,max(290,s.rightWidth-d));self?.applyResizableLayout()};h.dragged={[weak self]d in guard let self else{return};let u=max(1,self.arrangementCard.frame.height+self.inspectorCard.frame.height);s.arrangementFraction=min(.78,max(.42,s.arrangementFraction+d/u));self.applyResizableLayout()}}
