    private func enlargeTransportControls(){let w=transportCard.bounds.width,y:CGFloat=10;stopButton.frame=NSRect(x:w*.46-62,y:y,width:48,height:48);playButton.frame=NSRect(x:w*.46-5,y:y-3,width:54,height:54);recordButton.frame=NSRect(x:w*.46+58,y:y-3,width:54,height:54);timeLabel.frame=NSRect(x:w*.20,y:20,width:135,height:30);transportCard.subviews.first{$0.identifier?.rawValue=="open"}?.frame=NSRect(x:w-196,y:18,width:82,height:34);transportCard.subviews.first{$0.identifier?.rawValue=="save"}?.frame=NSRect(x:w-106,y:18,width:92,height:34)}
    func refreshEngineUI(){applyResizableLayout();let e=CompositionStudioEngine.shared;guard e.isReady else{return};playButton.title=e.isPlaying ? "❚❚":"▶";statusLabel.stringValue=e.isRecording ? "Aufnahme":(e.isPlaying ? "Wiedergabe":"Bereit");let x=max(0,e.positionSeconds),mi=Int(x)/60,se=Int(x)%60,ms=Int((x-floor(x))*1000);timeLabel.stringValue=String(format:"%02d:%02d.%03d",mi,se,ms);if let f=transportCard.subviews.compactMap({$0 as? NSTextField}).first(where:{$0.identifier?.rawValue=="tempo"}),f.currentEditor()==nil{f.stringValue=String(format:"Tempo\n%.2f",e.tempo)};syncLiveDAW()}
